-- Live objective presentation: imported route totals are not authoritative.

local function liveObjective(node)

 if node and ns.Adaptive then node=ns.Adaptive.DisplayStep(node)end

 if not node or node.kind~='objective' or not node.quest then return node end

 local ok,goals=pcall(function()return C_QuestLog and C_QuestLog.GetQuestObjectives(node.quest)end)

 if not ok or type(goals)~='table' then return node end

 -- Slot zero is an auxiliary route task (key/item preparation), not objective one.
 if node.slot==0 then return node end
 local goal=node.slot and goals[node.slot]

 if not goal and #goals==1 then goal=goals[1] end

 if type(goal)~='table' or type(goal.text)~='string' or goal.text=='' then return node end

 local current,total=tonumber(goal.numFulfilled),tonumber(goal.numRequired)

 local text=goal.text

 if current and total and total>0 and not text:find('%d+%s*/%s*%d+') then text=text..' ('..current..'/'..total..')' end

 local display={};for k,v in pairs(node)do display[k]=v end

 display.title=text

 -- Replace only the copied instruction, preserving route notes and source identity.

 local original=node.body or ''

 if original:sub(1,#(node.title or ''))==node.title then original=original:sub(#node.title+1) end

 display.body=text..'\n\n'..original:gsub('^%s+','')

 return display

end

ns.LiveObjectiveDisplay=liveObjective

-- Local advisory planning only; no casts, purchases, training or gameplay actions.

do

 local P=ns.ProfessionGuide;local C=ns.Retail.Client

 local function read(fn,...)if type(fn)=='function'then local ok,v=pcall(fn,...);if ok then return v end end end

 local sites={{["npcID"]=1651,["npc"]="Lee Brown",["name"]="Crystal Lake shore",["zone"]="Elwynn Forest",["mapID"]=1429,["x"]=47.61,["y"]=62.32,["minimumSkill"]=1,["minimumLevel"]=5,["faction"]="Alliance",["confidence"]="Documented fishery; NPC position is a shore/trainer approach anchor, not a guaranteed casting pixel."},{["npcID"]=1700,["npc"]="Paxton Ganter",["name"]="Iceflow Lake shore",["zone"]="Dun Morogh",["mapID"]=1426,["x"]=35.48,["y"]=40.22,["minimumSkill"]=1,["minimumLevel"]=5,["faction"]="Alliance",["confidence"]="Documented fishery; NPC position is a shore/trainer approach anchor, not a guaranteed casting pixel."},{["npcID"]=3607,["npc"]="Androl Oakhand",["name"]="Rut'theran shore",["zone"]="Teldrassil",["mapID"]=1438,["x"]=55.88,["y"]=93.51,["minimumSkill"]=1,["minimumLevel"]=5,["faction"]="Alliance",["confidence"]="Documented fishery; NPC position is a shore/trainer approach anchor, not a guaranteed casting pixel."},{["npcID"]=5493,["npc"]="Arnold Leland",["name"]="Stormwind canals",["zone"]="Stormwind City",["mapID"]=1453,["x"]=45.64,["y"]=58.43,["minimumSkill"]=75,["minimumLevel"]=5,["faction"]="Alliance",["confidence"]="Documented fishery; NPC position is a shore/trainer approach anchor, not a guaranteed casting pixel."}}

 P.ProfessionWindow={minimumLevel=5,preferredByLevel=8,serviceRadiusYards=650}

 P.FishingSites=sites

 local city={[1453]=true,[1455]=true,[1457]=true,[1947]=true,[1954]=true}

 local trainerIDs={Blacksmithing={514,5511,4258},Mining={5513,4254},Cooking={1430,5482,1355},Fishing={1651,5493,5161,1700,3607},['First Aid']={2329,5484,5150}}

 local function distance(pos,loc)

  if not pos or pos.status~='available'or not loc then return end

  local i,x,y=C.WorldPosition(pos.mapID,pos.x*100,pos.y*100);local j,a,b=C.WorldPosition(loc.mapID,loc.x,loc.y)

  if i and j==i and x and y and a and b then return math.sqrt((x-a)^2+(y-b)^2)end

 end

 function P.ProfessionContext()

  local pos=C.PlayerPosition();local character=C.Character();local sub=read(GetSubZoneText)or'';if type(sub)~='string'then sub=''end

  local starter=pos.status=='available'and pos.mapID==1429 and pos.x>=.40 and pos.x<=.54 and pos.y>=.28 and pos.y<=.51

  if sub:lower():find('northshire',1,true)then starter=true end

  local starterPending=false

  for _,n in ipairs(P.steps or{})do

   if not n.complete and(n.kind=='accept'or n.kind=='turnin'or n.kind=='objective')then

    local d=n.destination

    starterPending=d and n.level<=5 and d.mapID==1429 and d.x>=40 and d.x<=54 and d.y>=28 and d.y<=51 or false

    break

   end

  end

  return{pos=pos,level=character.level or 1,faction=character.faction,starter=starter,starterPending=starterPending,

   unsafe=read(UnitAffectingCombat,'player')==true or read(UnitIsDeadOrGhost,'player')==true or read(UnitOnTaxi,'player')==true or read(IsFlying)==true,

   city=city[pos.mapID]==true,resting=read(IsResting)==true}

 end

 function P.PlanFishing(rank,cap,context)

  local ctx=context or P.ProfessionContext();rank=tonumber(rank)or 0

  local result={baseSkill=rank,effectiveSkill=rank,poleBonus=0,lureBonus=0,cap=cap}

  if ctx.level<5 then result.reason='Fishing training begins at character level 5.';return result end

  if ctx.unsafe then result.reason='Finish combat or travel before fishing.';return result end

  if ctx.pos.status~='available'then result.reason='Player position unavailable; no fishing destination chosen.';return result end

  if rank==0 then result.reason='Learn Fishing first; this planner assumes a basic Fishing Pole and no lure.';return result end

  if cap and rank>=cap then

   result.reason='Your trained Fishing cap is reached. Unlock the next rank before further skill gains.'

   local training={

    [75]={minimumLevel=10,action='Train Journeyman Fishing manually at a nearby Fishing trainer.'},

    [150]={minimumLevel=20,npcID=2626,action='Review Expert Fishing - The Bass and You from Old Man Heming in Booty Bay. Check the book requirements and cost before buying.'},

    [225]={minimumLevel=35,npcID=12919,action='Review Nat Pagle, Angler Extreme with Nat Pagle in Dustwallow Marsh. This requires level 35 and Fishing 225; complete its fishing objectives manually.'},

    [300]={minimumLevel=60,npcID=18911,action='Review Master Fishing - The Art of Angling with Juno Dufrain in Zangarmarsh. Check its requirements before buying.'}}

   result.training=training[cap]

   if cap==75 and ctx.level<10 then result.reason='Journeyman Fishing requires character level 10; continue questing before this training stop.'end

   return result

  end

  for _,site in ipairs(sites)do

   if rank>=site.minimumSkill and ctx.level>=site.minimumLevel and(site.faction==ctx.faction or site.faction=='Neutral')then

    local yards=distance(ctx.pos,site)

    if yards and(not result.distance or yards<result.distance)then result.site=site;result.distance=yards end

   end

  end

  if not result.site then result.reason='No researched nearby fishery is eligible for your base skill and location. Do not use a higher-level zone just to meet a pacing goal.'end

  return result

 end

 local function nearbyTrainer(name,ctx)

  local best,dist

  for _,id in ipairs(trainerIDs[name]or{})do

   for _,loc in ipairs(ns.TBCNPCLocations and ns.TBCNPCLocations(id,'Trainer')or{})do

    if loc.faction==ctx.faction or loc.faction=='Neutral'then

     local d=distance(ctx.pos,loc);if d and(not dist or d<dist)then best,dist=loc,d end

    end

   end

  end

  return best,dist

 end

 function P.ApplyProfessionOpportunities()

  if not P.active then return end

  local ctx=P.ProfessionContext();local plans={};local trainers={}

  for _,node in ipairs(P.steps or{})do

   if node.kind=='profession'then

    node._originalBody=node._originalBody or node.body;node._originalDestination=node._originalDestination or node.destination

    node.body=node._originalBody;node.destination=node._originalDestination;node.deferred=false;node.deferReason=nil

    local skill=P.skills[node.profession];local reason

    if ctx.level<P.ProfessionWindow.minimumLevel then reason='Continue early questing before profession detours.'

    elseif ctx.unsafe then reason='Profession stop deferred during combat, death or travel.'

    elseif ctx.starter or(ctx.starterPending and ctx.level<P.ProfessionWindow.preferredByLevel)then reason='Finish the starting area before profession detours.'

    elseif ctx.pos.status~='available'then reason='Location unavailable; do not suggest a profession detour.'end

    if not skill then

     if not trainers[node.profession]then local loc,d=nearbyTrainer(node.profession,ctx);trainers[node.profession]={loc=loc,distance=d}end

     local trainer=trainers[node.profession]

     if trainer.loc then node.destination=trainer.loc end

     if not reason and not(ctx.city or ctx.resting or trainer.distance and trainer.distance<=P.ProfessionWindow.serviceRadiusYards)then reason='Wait until the quest route brings you near this profession trainer.'end

    elseif node.profession=='Fishing'and not node.complete then

     if not plans.Fishing then plans.Fishing=P.PlanFishing(skill.rank,skill.cap,ctx)end

     local plan=plans.Fishing

     node.body=string.format('Fishing: %d / %d. Route pacing goal: %d.\n\nAssumption: basic Fishing Pole (+0 skill), no lure. Effective skill used: %d.\n\n',skill.rank,skill.cap,node.target,skill.rank)

     node.destination=nil

     if plan.site then

      local site=plan.site;node.destination={mapID=site.mapID,x=site.x,y=site.y,name=site.name,areaTask=true}

      node.body=node.body..string.format('Closest researched eligible water: %s, %s (%.2f, %.2f), about %.0f yards. This is a shoreline/trainer approach anchor, not a guaranteed casting spot.\n\n',site.name,site.zone,site.x,site.y,plan.distance)

      node.body=node.body..'Stay on an accessible cleared shore and check for hostile creatures. Fish can still escape with no lure; lower-tier water remains useful for skill gains. Stop at the pacing goal or when your route should continue.\n\n'

      if plan.distance>P.ProfessionWindow.serviceRadiusYards then node.body=node.body..'This is a detour: wait until your quest route passes nearby rather than interrupting current quests.\n\n'end

      if not reason and ctx.level<P.ProfessionWindow.preferredByLevel and plan.distance>P.ProfessionWindow.serviceRadiusYards then reason='Wait until the route reaches eligible fishing water.'end

     else node.body=node.body..(plan.reason or'No suitable researched water found.')..'\n\n';reason=reason or plan.reason end

     if plan.training and ctx.level>=plan.training.minimumLevel then

      local location,yards

      if plan.training.npcID then

       for _,loc in ipairs(ns.TBCNPCLocations and ns.TBCNPCLocations(plan.training.npcID,'Training')or{})do

        if loc.faction==ctx.faction or loc.faction=='Neutral'then local d=distance(ctx.pos,loc);if d and(not yards or d<yards)then location,yards=loc,d end end

       end

      else location,yards=nearbyTrainer('Fishing',ctx)end

      node.body=node.body..'\n\n'..plan.training.action

      if location and yards and yards<=P.ProfessionWindow.serviceRadiusYards and not ctx.starter and not ctx.unsafe and not(ctx.starterPending and ctx.level<P.ProfessionWindow.preferredByLevel)then

       node.destination=location;reason=nil

      end

     end

     node.body=node.body..'Keep useful fish for Cooking. Use only recipes confirmed in your own Cooking book and check their skill/material requirements; no recipe or drop is assumed known. All fishing, cooking and training remain manual.'

    elseif not reason and node.profession~='Mining'then

     local d=distance(ctx.pos,node.destination)

     if node.profession=='Blacksmithing'and not(d and d<=P.ProfessionWindow.serviceRadiusYards)then

      reason='Wait until your route reaches the researched forge/anvil stop; do not return there solely for a pacing target.'

     elseif not(ctx.city or ctx.resting or d and d<=P.ProfessionWindow.serviceRadiusYards)then

      local book=P.book[node.profession];local ready=false

      for _,recipe in ipairs(book and book.values or{})do if recipe.enough then ready=true;break end end

      if not ready then reason='Wait for a nearby service stop or a known recipe with materials already available.'end

     end

    end

    if reason and not node.complete then node.deferred=true;node.deferReason=reason end

   end

  end

  P.firstPending=nil;for _,node in ipairs(P.steps or{})do if not node.complete and not node.deferred then P.firstPending=node.id;break end end

 end

 local refresh=P.Refresh

 P.Refresh=function(...)local out=refresh(...);P.ApplyProfessionOpportunities();return out end

 local monitor=CreateFrame('Frame');local elapsed=0;local last

 local function update()

  if not P.active then return end

  local pos=C.PlayerPosition();local context=P.ProfessionContext();local signature=tostring(pos.mapID)..':'..tostring(pos.status)..':'..tostring(context.unsafe)..':'..tostring(context.resting)

  local moved=pos.status=='available'and last and last.x and last.y and last.mapID==pos.mapID and((pos.x-last.x)^2+(pos.y-last.y)^2)>.000025

  if not last or signature~=last.signature or moved then

   last={signature=signature,mapID=pos.mapID,x=pos.x,y=pos.y}

   P.ApplyProfessionOpportunities()

   if ns.NormalUI and ns.NormalUI.root then ns.NormalUI.model:Reconcile();ns.NormalUI.Refresh(true)end

  end

 end

 for _,event in ipairs({'PLAYER_REGEN_ENABLED','PLAYER_REGEN_DISABLED','ZONE_CHANGED','ZONE_CHANGED_NEW_AREA','PLAYER_UPDATE_RESTING'})do pcall(monitor.RegisterEvent,monitor,event)end

 monitor:SetScript('OnEvent',update)

 monitor:SetScript('OnUpdate',function(_,dt)elapsed=elapsed+dt;if elapsed>=2 then elapsed=0;update()end end)

end



local GuideView={}

function GuideView.New()

 local self={steps={},goals={Questing=true,Dungeons=true,Gathering=true,Crafting=true},view="All"}

 function self:Visible()

  self.steps=ns.FarmingPlanner and ns.FarmingPlanner.route and ns.FarmingPlanner.route.steps or P.steps;local out={}

  for _,node in ipairs(self.steps)do

   if not node.complete and not node.deferred and node.category~="Gear Rewards" and self.goals[node.category] and (self.view=="All" or self.view==node.category or self.view=="Questing" and node.category=="Dungeons")then out[#out+1]=node end

  end

  return out

 end

 function self:Current()for _,node in ipairs(self:Visible())do if node.id==self.index then return node end end end

 function self:Reconcile()

  if not self:Current() or (self:Current().complete and not self.browsing)then local visible=self:Visible();self.index=nil;for _,n in ipairs(visible)do if not n.complete then self.index=n.id;break end end;self.index=self.index or (visible[#visible]and visible[#visible].id) end

