  status:ClearAllPoints();status:SetPoint("TOPLEFT",bodyScroll,"BOTTOMLEFT",0,compact and -12 or -16)

  status:SetWidth(bodyScroll:GetWidth());status:SetHeight(24);status:SetJustifyH("CENTER")

