local function world(p)if p then return ns.Retail.Client.WorldPosition(p.mapID,p.x,p.y)end end

local function dist(a,b)local i,x,y=world(a);local j,u,v=world(b);if i and i==j and x and y and u and v then return math.sqrt((x-u)^2+(y-v)^2)end end

