function A.Initialize()

 if not ns.Retail.ready or not ns.Retail.storageWritable then return false end

 local db=GrindingForeverAnniversaryCharacterDB;if type(db)~='table'or(db.version~=nil and db.version~=1)then return false end

 if db.catalog==nil then db.catalog={version=1,enabled=not G.data or G.data.enabled~=false,events={},next=1,sequence=1,known={},npcs={}}end

 if type(db.catalog)~='table'or db.catalog.version~=1 then return false end

 A.data=db.catalog;A.data.known=A.data.known or {};A.data.npcs=A.data.npcs or {};G.SetEnabled(A.data.enabled);A.Update();return true

end

function A.Record(kind,fields)

 local d=A.data;if not d or not d.enabled then return end

 local row={kind=kind,time=call(GetServerTime),level=call(UnitLevel,'player'),position=pos(),sequence=d.sequence};for k,v in pairs(fields or {})do row[k]=v end

