end

function A.SetEnabled(value)

 if not A.data and not A.Initialize()then return false end

 A.data.enabled=not not value;G.SetEnabled(value);A.pendingCraft=nil;A.loot=nil;A.questStates={};A.Update();return true

end

function A.Update()

 local enabled=A.data and A.data.enabled or false;if ns.QuestObserver then ns.QuestObserver.enabled=enabled end

 if N.recordToggle then N.recordToggle.label:SetText('Collect activity data');N.recordToggle:SetCheckedVisual(enabled)end

 if N.gatherToggle then N.gatherToggle:Hide()end

 if N.recordStatus then local c=0;for _ in pairs(A.data and A.data.events or {})do c=c+1 end;N.recordStatus:SetText((enabled and'Collecting'or'Paused')..' - '..c..'/2000 activity records');N.recordStatus:ClearAllPoints();N.recordStatus:SetPoint('TOPLEFT',N.settingsFrame,'TOPLEFT',16,-218)end

end

function A.ScanBook()

 if not A.data or not A.data.enabled or call(GetTradeSkillIsLinked)==true then return end

 local line=call(GetTradeSkillLine);if not line or line=='UNKNOWN'then return end

 local names={};for i=1,(call(GetNumTradeSkills)or 0)do local name,kind=call(GetTradeSkillInfo,i);if name and kind~='header'then names[name]=true end end

 for spell,r in pairs(ns.TBCRecipes)do if ns.TBCProfessions[r.professionID]==line and names[r.name]then if not A.data.known[spell]then A.data.known[spell]=true;A.bookRevision=(A.bookRevision or 0)+1 end end end

local selected=call(GetTradeSkillSelectionIndex)

 if selected and selected>0 then local name=call(GetTradeSkillInfo,selected);local mats={};for i=1,(call(GetTradeSkillNumReagents,selected)or 0)do local link=call(GetTradeSkillReagentItemLink,selected,i);local id=type(link)=='string'and tonumber(link:match('item:(%d+)'));local _,_,need=call(GetTradeSkillReagentInfo,selected,i);if id and type(need)=='number'then mats[id]=need end end

  local signature=tostring(line)..':'..tostring(name);for id,qty in pairs(mats)do signature=signature..':'..id..'='..qty end

  if A.lastRecipeObservation~=signature then A.lastRecipeObservation=signature;A.Record('recipe-observed',{profession=line,recipe=name,reagents=mats})end

 end

end

function A.ScanCraftBook()

 if not A.data or not A.data.enabled then return end

 local line=call(GetCraftDisplaySkillLine);local names={}

 for i=1,(call(GetNumCrafts)or 0)do local name,_,kind=call(GetCraftInfo,i);if name and kind~='header'then names[name]=true end end

 for spell,r in pairs(ns.TBCRecipes)do if names[r.name]and(not line or ns.TBCProfessions[r.professionID]==line)then if not A.data.known[spell]then A.data.known[spell]=true;A.bookRevision=(A.bookRevision or 0)+1 end end end

 local selected=call(GetCraftSelectionIndex);if selected and selected>0 then local name=call(GetCraftInfo,selected);local mats={}

  for i=1,(call(GetCraftNumReagents,selected)or 0)do local link=call(GetCraftReagentItemLink,selected,i);local id=type(link)=='string'and tonumber(link:match('item:(%d+)'));local _,_,qty=call(GetCraftReagentInfo,selected,i);if id and type(qty)=='number'then mats[id]=qty end end

  local signature=tostring(line)..':'..tostring(name);for id,qty in pairs(mats)do signature=signature..':'..id..'='..qty end

  if A.lastRecipeObservation~=signature then A.lastRecipeObservation=signature;A.Record('recipe-observed',{profession=line,recipe=name,reagents=mats})end

 end

end

function A.Known(spell)

 if A.data and A.data.known[spell]then return true end

 local v=call(IsPlayerSpell,spell);if type(v)=='boolean'then return v end

 v=call(IsSpellKnown,spell);if type(v)=='boolean'then return v end

end

function A.Skills()

 local out={};for i=1,(call(GetNumSkillLines)or 0)do local name,header,_,rank=call(GetSkillLineInfo,i);if name and not header and type(rank)=='number'then out[name]=rank end end;return out

end

function A.QuestState(id,baseline)

 if not id then return end

 local objectives=call(C_QuestLog and C_QuestLog.GetQuestObjectives,id);local parts={};local rows={}

 for i,v in ipairs(type(objectives)=='table'and objectives or {})do rows[i]={text=v.text,count=v.numFulfilled,required=v.numRequired,finished=v.finished};parts[i]=tostring(v.numFulfilled)..'/'..tostring(v.numRequired)..':'..tostring(v.finished)end

 local key=table.concat(parts,';');A.questStates=A.questStates or {};local old=A.questStates[id];A.questStates[id]=key

 if not baseline and old and key~=old then A.Record('quest-progress',{questID=id,objectives=rows})end

end

function A.ScanQuests()

 if not A.data or not A.data.enabled then return end

 local total=call(C_QuestLog and C_QuestLog.GetNumQuestLogEntries or GetNumQuestLogEntries)or 0

 for i=1,total do local info=call(C_QuestLog and C_QuestLog.GetInfo,i);local id=info and not info.isHeader and info.questID

  if not info then local name,_,_,header,_,_,_,qid=call(GetQuestLogTitle,i);if name and not header then id=qid end end

  if id then A.QuestState(id,false)end

 end

end

-- Vendor index stores IDs only. Coordinates and faction are read from the installed DB.

function A.IndexNPC(id)

 local row=A.Meta('X-Npc-'..id..'-S');local spawns=A.Meta('X-Npc-'..id..'-7');if type(row)~='table'or not friendly(row[13])or type(spawns)~='table'then return end

 for area,points in pairs(spawns)do local map=ns.TBCData.areas[area];if map and A.outdoorMaps[map]and type(points)=='table'then

  for _,p in ipairs(points)do if type(p)=='table'and valid(p[1],p[2])then local v={npcID=id,name=row[1],mapID=map,x=p[1],y=p[2],flags=row[15]or 0};v.instance,v.wx,v.wy=world(v);A.vendors[#A.vendors+1]=v;break end end

 end end

end

function A.BeginIndex()

 if A.queue then return end;A.queue={};local p=pos();local first,rest={},{}

 for area,ids in pairs(A.knownVendors)do for _,id in ipairs(ids)do local list=p and ns.TBCData.areas[area]==p.mapID and first or rest;list[#list+1]=id end end

 for _,list in ipairs({first,rest})do for _,id in ipairs(list)do A.queue[#A.queue+1]=id end end;A.queueAt=1

end

function A.IndexNext(limit)

 A.BeginIndex();for i=1,limit or 4 do local id=A.queue[A.queueAt];if not id then A.vendorIndexComplete=true;return end;A.queueAt=A.queueAt+1;A.IndexNPC(id)end

end

function A.NearestVendor(ids,repair)

 local allow;if ids then allow={};for _,id in ipairs(ids)do allow[id]=true end end

 local p=pos();local best,distance;if not p then return end;local instance,x,y=world(p)

 for _,v in ipairs(A.vendors)do if(not allow or allow[v.npcID])and(not repair or math.floor(v.flags/4096)%2==1)then local d=instance and instance==v.instance and math.sqrt((x-v.wx)^2+(y-v.wy)^2);if d and(not distance or d<distance)then best,distance=v,d end end end

