-- Optional recipe opportunities are scoped to visits; skipping never marks source quests done.

function A.RecipeCandidates(v)

 local skills=A.Skills();local out={}

 for _,source in ipairs(A.recipesByVendor[v.npcID]or {})do local spell,r=source.spell,source.fact;local prof=ns.TBCProfessions[r.professionID];local rank=skills[prof]

  if rank and type(r.requiredSkill)=='number'and math.abs(r.requiredSkill-rank)<=25 and r.itemId and A.Known(spell)==false then

   for _,id in ipairs(r.sources and r.sources.v or {})do if id==v.npcID then out[#out+1]={spell=spell,fact=r,profession=prof};break end end

  end

 end

 table.sort(out,function(a,b)return a.fact.requiredSkill<b.fact.requiredSkill end);return out

end

function A.ScanOffers()

 if F.route or call(UnitAffectingCombat,'player')or call(UnitIsDeadOrGhost,'player')then return end

 local p=pos();if not p then return end;local changed=false;local active={};for _,o in ipairs(A.offers)do if not o.deferred and A.Known(o.spellID)~=true then active[#active+1]=o else changed=true end end;A.offers=active;local instance,x,y=world(p)

 for _,v in ipairs(A.vendors)do local d=instance and v.instance==instance and math.sqrt((x-v.wx)^2+(y-v.wy)^2);local visit=A.visits[v.npcID]

  if d and d<=90 then

   local signature=tostring(A.bookRevision or 0)..':'..tostring(A.offerRevision or 0);local skills=A.Skills();for _,name in ipairs({'Cooking','Blacksmithing','Tailoring','Leatherworking','Engineering','Alchemy','Enchanting','First Aid','Jewelcrafting'})do signature=signature..':'..tostring(skills[name])end

   if not visit or not visit.inside or visit.signature~=signature then visit={inside=true,number=(visit and visit.inside and visit.number or(visit and visit.number or 0)+1),signature=signature};A.visits[v.npcID]=visit

    for _,c in ipairs(A.RecipeCandidates(v))do local key=v.npcID..':'..c.spell..':'..visit.number

     local duplicate=A.deferred[v.npcID..':'..c.spell]==visit.number;for _,o in ipairs(A.offers)do if o.vendorID==v.npcID and o.spellID==c.spell and not o.deferred then duplicate=true end end

     if not duplicate and #A.offers<3 then local f=c.fact;local owned=count(f.itemId);A.offers[#A.offers+1]={id='vendorrecipe:'..key,kind='vendorRecipe',category='Crafting',spellID=c.spell,itemID=f.itemId,vendorID=v.npcID,visit=visit.number,title='Recipe: '..f.name..' - '..v.name,destination=v,

      body='Optional recipe stop: '..itemName(f.itemId)..(owned and owned>0 and' (already in your bags; avoid duplicate purchases)'or'')..'\n'..c.profession..' skill '..f.requiredSkill..'. This recipe is not learned according to the available spell/book evidence.\n\nVendor: '..v.name..'. Price and stock must be checked at the vendor.\nSkip defers this opportunity until another visit or another vendor with the same recipe. Purchases and learning are manual.'};changed=true

     end;if #A.offers>=3 then break end

    end

   end

  elseif visit and visit.inside and(not d or d>140)then visit.inside=false;for _,o in ipairs(A.offers)do if o.vendorID==v.npcID and not o.deferred then o.deferred=true;changed=true end end

  end

