-- Objective-area source positions support GPS arrival checks.

local function objectiveKey(node)

 if node and node.kind=='objective'and node.targetID then return tostring(node.quest)..':'..tostring(node.targetKind)..':'..tostring(node.targetID)end

end

-- Live quest-item loot is stronger local evidence than an imported single waypoint.

-- Ephemeral approach positions are not persisted as exact creature spawn coordinates.

function A.ObserveObjectiveLoot()

 if F.route then return end

 local node=N.model:Current();local key=objectiveKey(node)

 if not key or node.targetKind~='item'then return end

 local matched=false

 for slot=1,call(GetNumLootItems)or 0 do

  local link=call(GetLootSlotLink,slot);local item=type(link)=='string'and tonumber(link:match('item:(%d+)'))

  if item==node.targetID then matched=true;break end

 end

 if not matched then return end

 local p=pos();if not p then return end;p.instance,p.wx,p.wy=world(p);if not p.instance or not p.wx or not p.wy then return end

 A.objectiveSites=A.objectiveSites or {};local sites=A.objectiveSites[key]or{}

 local near=false;for _,site in ipairs(sites)do if site.instance==p.instance and math.sqrt((site.wx-p.wx)^2+(site.wy-p.wy)^2)<25 then near=true end end

 if not near then p.evidence='observed_player_at_quest_item_loot';sites[#sites+1]=p;if #sites>12 then table.remove(sites,1)end;A.objectiveSites[key]=sites;A.siteRevision=(A.siteRevision or 0)+1 end

 local count=0;for _ in pairs(A.objectiveSites)do count=count+1 end

 if count>16 then for old in pairs(A.objectiveSites)do if old~=key then A.objectiveSites[old]=nil;break end end end

 A.hot=nil;N.Tick()

end

function A.BuildHotspot(node)

 if not node or node.kind~='objective'or F.route then A.hot=nil;return end

 local p=pos();local key=node.id..':'..tostring(p and p.mapID)..':'..tostring(A.siteRevision or 0)

 if A.hot and A.hot.key==key then return A.hot end

 local ids=node.targetKind=='npc'and{node.targetID}or node.targetKind=='item'and A.Meta('X-Item-'..tostring(node.targetID)..'-2')or nil

 local sources,seen={},{}

 for _,list in ipairs({type(ids)=='table'and ids or{},node.mobIDs or{}})do for _,id in ipairs(list)do if not seen[id]then sources[#sources+1]=id;seen[id]=true end end end

 local points={};local instance,xp,yp=world(p)

 for _,site in ipairs(A.objectiveSites and A.objectiveSites[objectiveKey(node)]or{})do if site.instance==instance then points[#points+1]=site end end

 for _,id in ipairs(sources)do local data=A.Meta('X-Npc-'..id..'-7')

  for area,spawns in pairs(type(data)=='table'and data or{})do local map=ns.TBCData.areas[tonumber(area)or area]

   if p and map and type(spawns)=='table'then for _,q in ipairs(spawns)do if valid(q[1],q[2])then

    local point={mapID=map,x=q[1],y=q[2]};point.instance,point.wx,point.wy=world(point)

    if instance and point.instance==instance and point.wx and point.wy and math.sqrt((point.wx-xp)^2+(point.wy-yp)^2)<=4000 then points[#points+1]=point end

    if #points>=256 then break end

   end end end

  end;if #points>=256 then break end

 end

 if #points==0 then A.hot=nil;return end

 A.hot={key=key,mapID=points[1].mapID,points=points,title=node.title}

