 A.recentLoot=A.recentLoot or {};for guid,row in pairs(A.loot or {})do

  if not A.recentLoot[guid]or now()-A.recentLoot[guid]>300 then A.recentLoot[guid]=now();local stat=A.data.npcs[row.npcID]

   if not stat then local n=0;for _ in pairs(A.data.npcs)do n=n+1 end;if n>=300 then local old;for id in pairs(A.data.npcs)do old=id;break end;A.data.npcs[old]=nil end;stat={samples=0,items={}};A.data.npcs[row.npcID]=stat end

   stat.samples=stat.samples+1;A.dropRevision=(A.dropRevision or 0)+1;for item in pairs(row.items)do local size=0;for _ in pairs(stat.items)do size=size+1 end;if stat.items[item]or size<64 then stat.items[item]=(stat.items[item]or 0)+1 end end

