function A.DropLines(id)

 A.tooltipCache=A.tooltipCache or {};local cached=A.tooltipCache[id];if cached and cached.revision==A.dropRevision then return cached.lines end

 local out={};local candidates={};for _,item in ipairs(A.dropIndex[id]or {})do candidates[item]=true end

 for item,ids in pairs(F.skinSources)do for _,npc in ipairs(ids)do if npc==id then out[#out+1]=itemName(item)..': Skinning source; chance not recorded'end end end

