 for item in pairs(candidates)do

  local hits=stat and(stat.items[item]or 0);local text=itemName(item)..': '

  if hits then text=text..string.format('%.1f%% observed (%d/%d sampled corpses)',100*hits/stat.samples,hits,stat.samples)

   local sum,total=0,0;for npc,s in pairs(A.data.npcs)do local known=s.items[item]~=nil;for _,id in ipairs(A.dropIndex[npc]or {})do if id==item then known=true;break end end;if known and s.samples>=20 then sum=sum+(s.items[item]or 0);total=total+s.samples end end

   if stat.samples>=20 and total>=40 and hits/stat.samples>=sum/total then text=text..' - average or above in recorded sources'end

  if stat.samples<20 then text=text..' - small sample'end

  else text=text..'known material source; TBC chance not recorded'end

  out[#out+1]=text

