function A.AttachTooltip()

 if not GameTooltip or A.tooltipAttached then return end

 local header='Grinding Forever - useful materials'

 local function annotate(tip,data)

  local _,unit=call(tip.GetUnit,tip)

  local guid=type(data)=='table'and data.guid or call(tip.GetUnitGUID,tip)

  if not guid and not unit then

   local first=GameTooltipTextLeft1 and call(GameTooltipTextLeft1.GetText,GameTooltipTextLeft1)

   local mouseName=call(UnitName,'mouseover');if not first or first~=mouseName then return end

  end

  local id=entry(guid)or entry(call(UnitGUID,unit or'mouseover'))

  if not id then return end

  -- Base tooltips rebuild in place; inspect existing lines rather than permanently marking a GUID.

  local count=call(tip.NumLines,tip)or 0;local name=call(tip.GetName,tip)or'GameTooltip'

  for i=1,count do local line=_G[name..'TextLeft'..i];if line and call(line.GetText,line)==header then return end end

  local lines=A.DropLines(id)

  if #lines>0 then local existing={};for i=1,count do local line=_G[name..'TextLeft'..i];local value=line and call(line.GetText,line);if value then existing[value]=true;local label=value:match('^(.-):%s*%d+%s*/%s*%d+$');if label then existing[label]=true end end end;for i=1,math.min(6,#lines)do if not existing[lines[i]]then tip:AddLine(lines[i],.9,.8,.6,true)end end;tip:Show()end

 end

 local modern,legacy,fallback=false,false,false

 if TooltipDataProcessor and TooltipDataProcessor.AddTooltipPostCall and Enum and Enum.TooltipDataType and Enum.TooltipDataType.Unit then

  modern=pcall(TooltipDataProcessor.AddTooltipPostCall,Enum.TooltipDataType.Unit,annotate)

 end

 if GameTooltip.HookScript then

  legacy=pcall(GameTooltip.HookScript,GameTooltip,'OnTooltipSetUnit',annotate)

  local elapsed=0

  fallback=pcall(GameTooltip.HookScript,GameTooltip,'OnUpdate',function(tip,dt)

   elapsed=elapsed+(dt or 0);if elapsed<.2 then return end;elapsed=0

   if call(tip.IsShown,tip)then annotate(tip)end

  end)

 end

 A.tooltipAttached=modern or legacy or fallback;A.tooltipUnavailable=not A.tooltipAttached

 A.tooltipHooks={modern=modern,legacy=legacy,fallback=fallback}

end



