function O.Draft()

 local lines={'Grinding Forever - Activity draft','Observed events only; review required. Not activated as a guide.','Positions are observed player positions, not guaranteed NPC locations.',''};local rows={};for _,row in pairs(A.data and A.data.events or {})do rows[#rows+1]=row end;table.sort(rows,function(a,b)return a.sequence<b.sequence end)

 for _,r in ipairs(rows)do local p=r.position;lines[#lines+1]=r.sequence..'. '..r.kind..(r.questID and(' quest '..r.questID)or r.spellID and(' spell '..r.spellID)or'')..(p and string.format(' | map%d %.2f, %.2f',p.mapID,p.x,p.y)or'')end

 for _,r in ipairs(rows)do

  if r.objectives then for _,o in ipairs(r.objectives)do lines[#lines+1]='  Quest '..tostring(r.questID)..': '..tostring(o.text or'objective')..' '..tostring(o.count or'?')..'/'..tostring(o.required or'?')end end

  if r.recipe then lines[#lines+1]='  Recipe: '..r.recipe end

  if r.reagents then for id,qty in pairs(r.reagents)do lines[#lines+1]='  Reagent '..id..' x'..qty end end

  if r.productID then lines[#lines+1]='  Output item '..r.productID..(r.count and(' x'..r.count)or' (cast evidence only)')end

