function A.Merchant(id)

 if not id or not A.data or not A.data.enabled then return end

 local stock={};for i=1,math.min(100,call(GetMerchantNumItems)or 0)do local link=call(GetMerchantItemLink,i);local item=type(link)=='string'and tonumber(link:match('item:(%d+)'))

  if item and(A.recipeByItem[item]or A.reagents[item])then local _,_,price,quantity,available,usable,extended=call(GetMerchantItemInfo,i);stock[item]={price=price,quantity=quantity,available=available,extendedCost=extended or false}end

 end

 A.stock=A.stock or {};A.stock[id]=stock;A.Record('vendor-stock',{npcID=id,items=stock})

end

function A.Event(event,...)

 if event=='PLAYER_LOGIN'or event=='PLAYER_ENTERING_WORLD'then A.Initialize();A.AttachTooltip();A.BeginIndex();return end

 if not A.data and not A.Initialize()then return end

 local a,b,c=...

 if event=='TRADE_SKILL_UPDATE'or event=='TRADE_SKILL_SHOW'then A.ScanBook()

 elseif event=='CRAFT_UPDATE'or event=='CRAFT_SHOW'then A.ScanCraftBook()

 elseif event=='GET_ITEM_INFO_RECEIVED'then A.tooltipCache={};if N.selectedRecipe and N.selectedRecipe.id==a then N.RefreshRecipes()end

 elseif event=='SKILL_LINES_CHANGED'and A.data.enabled then local skills=A.Skills();local before=A.skills or {};for name,rank in pairs(skills)do if before[name]and before[name]~=rank then A.Record('profession-skill',{profession=name,before=before[name],after=rank})end end;A.skills=skills

 elseif event=='QUEST_ACCEPTED'and A.data.enabled then local id=tonumber(b)or tonumber(a);if id then A.Record('quest-accepted',{questID=id,npcID=entry(call(UnitGUID,'npc'))});A.QuestState(id,true)end

 elseif event=='QUEST_TURNED_IN'and A.data.enabled then A.Record('quest-turned-in',{questID=tonumber(a),npcID=entry(call(UnitGUID,'npc'))})

 elseif event=='QUEST_LOG_UPDATE'then A.scanPending=true

 elseif event=='UNIT_SPELLCAST_START'and a=='player'and A.data.enabled then

  local spell=tonumber(c);local recipe=spell and ns.TBCRecipes[spell];if recipe and recipe.craftedItemId then A.pendingCraft={spellID=spell,product=recipe.craftedItemId,before=count(recipe.craftedItemId),started=now()}end

 elseif event=='BAG_UPDATE_DELAYED'and A.pendingCraft and A.data.enabled then

  local pending=A.pendingCraft;local after=count(pending.product);if after and pending.before and pending.succeeded and now()-pending.started<=5 and after>pending.before then A.Record('craft-output-inventory-delta',{spellID=pending.spellID,productID=pending.product,count=after-pending.before,evidence='inventory_change_after_successful_craft_cast'});A.pendingCraft=nil elseif now()-pending.started>5 then A.pendingCraft=nil end

 elseif event=='UNIT_SPELLCAST_SUCCEEDED'and a=='player'and A.data.enabled then

  local spell=tonumber(c);if A.pendingCraft and A.pendingCraft.spellID==spell then A.pendingCraft.succeeded=true end;if spell and ns.TBCRecipes[spell]and next(ns.TBCRecipes[spell].reagents or {})then A.Record('craft-cast-succeeded',{spellID=spell,productID=ns.TBCRecipes[spell].craftedItemId})end

  if spell==8613 or spell==8617 or spell==8618 or spell==10768 or spell==32678 then A.skinningUntil=now()+8 end

 elseif event=='LOOT_READY'or event=='LOOT_OPENED'then A.ObserveObjectiveLoot();A.LootSnapshot()

 elseif event=='LOOT_CLOSED'then A.CommitLoot()

 elseif event=='MERCHANT_SHOW'then local id=entry(call(UnitGUID,'npc'));if id then A.Record('vendor-visit',{npcID=id});A.Merchant(id);local visit=A.visits[id];A.visits[id]={inside=true,number=(visit and visit.number or 0)+1};for _,offer in ipairs(A.offers)do if offer.vendorID==id then offer.deferred=true end end;A.offerRevision=(A.offerRevision or 0)+1;A.ScanOffers() end

 end

end

local frame=CreateFrame('Frame');for _,event in ipairs({'PLAYER_LOGIN','PLAYER_ENTERING_WORLD','QUEST_ACCEPTED','QUEST_TURNED_IN','QUEST_LOG_UPDATE','SKILL_LINES_CHANGED','TRADE_SKILL_UPDATE','TRADE_SKILL_SHOW','CRAFT_UPDATE','CRAFT_SHOW','UNIT_SPELLCAST_START','UNIT_SPELLCAST_SUCCEEDED','BAG_UPDATE_DELAYED','LOOT_READY','LOOT_OPENED','LOOT_CLOSED','GET_ITEM_INFO_RECEIVED','MERCHANT_SHOW'})do pcall(frame.RegisterEvent,frame,event)end

