local elapsed,indexElapsed,questElapsed=0,0,0

frame:SetScript('OnUpdate',function(_,dt)

 elapsed=elapsed+dt;indexElapsed=indexElapsed+dt;questElapsed=questElapsed+dt

 if A.scanPending and questElapsed>=.25 then questElapsed=0;A.scanPending=false;A.ScanQuests()end

 if not A.vendorIndexComplete and indexElapsed>=.15 then indexElapsed=0;A.IndexNext(4)end

 if elapsed>=3 then elapsed=0;local node=N.model and N.model:Current();if node and(node.kind=='sell'or node.kind=='buy'or node.kind=='repair')then local v=A.VendorDestination(node);if v and A.lastVendorID~=v.npcID then A.lastVendorID=v.npcID;N.Refresh(true)end end;A.ScanOffers()end

end)

local previous=SlashCmdList.GRINDINGFOREVER

SlashCmdList.GRINDINGFOREVER=function(text)

 local s=(text or''):lower():match('^%s*(.-)%s*$')

 if s=='record on'or s=='collect on'then O.Start();return

 elseif s=='record off'or s=='collect off'then O.Stop();return

 elseif s=='record export'or s=='collect export'then O.Export();return

 elseif s=='collect status'or s=='record status'then A.Update();ns.Print(N.recordStatus and N.recordStatus:GetText()or'Activity catalog unavailable.');return

 elseif s=='record draft'then O.Draft();ns.Print('Activity draft built; use Export draft.');return

 elseif s=='gather on'then O.Start();return previous(text)

 elseif s=='gather off'then O.Stop();return previous(text)end

 return previous(text)

end

ns.RegisterMessage('GF_LOGIN',function()A.Initialize();O.enabled=A.data and A.data.enabled;A.BeginIndex();A.AttachTooltip()end)

A.Initialize();O.enabled=A.data and A.data.enabled;A.AttachTooltip()



end)(hotAddon,hotNS);



N.MakeButton=btn;N.MakeCheckbox=checkbox;N.MakeText=text;N.PlainOption=plainMenuOption

N.WorkflowBody=function()return body,bodyScroll,stepLabel,bodyContent,status end

N.WorkflowLive=liveObjective

N.WorkflowRelayout=layout





