local S=ns.DraeneiShaman;local N,P,C=ns.NormalUI,ns.ProfessionGuide,ns.Retail.Client

local function call(f,...)if type(f)=='function'then local ok,a,b=pcall(f,...);if ok then return a,b end end end

local function applicable()local c=C.Character();return ns.Retail.ready and c.faction=='Alliance'and c.race=='Draenei'and c.class=='SHAMAN',c end

local function saved()local db=GrindingForeverAnniversaryCharacterDB;if type(db)~='table'then db={};GrindingForeverAnniversaryCharacterDB=db end;db.draeneiShaman=db.draeneiShaman or{manual={}};return db.draeneiShaman end

local function state(q)return C.QuestState(q)or{}end

