-- Cooking, First Aid, Fishing and combined Fishing/Cooking guides (2026-10-30).

L.stages={

 Leatherworking={{20,'Light Leather'},{45,'Light Armor Kit'},{55,'Handstitched Leather Cloak'},{100,'Embossed Leather Gloves'},{120,'Fine Leather Belt'},{135,'Dark Leather Boots','Dark Leather Belt'},{150,'Dark Leather Pants'},{155,'Heavy Leather','Heavy Leather Ball'},{165,'Cured Heavy Hide','Heavy Armor Kit'},{180,'Heavy Armor Kit'},{190,'Barbaric Shoulders','Guardian Pants','Barbaric Leggings'},{200,'Guardian Gloves','Barbaric Leggings'},{205,'Thick Armor Kit'},{235,'Nightscape Headband'},{250,'Nightscape Pants'},{265,'Rugged Armor Kit'},{290,'Wicked Leather Bracers'},{300,'Wicked Leather Headband'},{325,'Knothide Armor Kit','Wicked Leather Belt'},{335,'Heavy Knothide Leather'},{350,'Thick Draenic Vest'},{365,'Heavy Knothide Armor Kit'},{370,'Drums of Battle'},{375,'Drums of Panic','Drums of Battle'}},

 ['First Aid']={{40,'Linen Bandage'},{80,'Heavy Linen Bandage'},{115,'Wool Bandage'},{150,'Heavy Wool Bandage'},{180,'Silk Bandage'},{210,'Heavy Silk Bandage'},{240,'Mageweave Bandage'},{260,'Heavy Mageweave Bandage'},{290,'Runecloth Bandage'},{330,'Heavy Runecloth Bandage'},{360,'Netherweave Bandage'},{375,'Heavy Netherweave Bandage'}},

 Cooking={{40,'Spice Bread','Brilliant Smallfish','Roasted Boar Meat'},{65,'Roasted Boar Meat','Smoked Bear Meat','Spiced Wolf Meat','Brilliant Smallfish','Slitherskin Mackerel'},{110,'Boiled Clams','Coyote Steak','Longjaw Mud Snapper','Bat Bites','Strider Stew'},{130,'Crab Cake','Dry Pork Ribs','Bristle Whisker Catfish','Cooked Crab Claw'},{175,'Curiously Tasty Omelet','Bristle Whisker Catfish','Hot Lion Chops'},{225,'Roast Raptor','Soothing Turtle Bisque','Mithril Head Trout'},{250,'Spotted Yellowtail','Monster Omelet','Tender Wolf Steak','Filet of Redgill'},{285,'Juicy Bear Burger','Charred Bear Kabobs','Poached Sunscale Salmon','Nightfin Soup'},{300,'Smoked Desert Dumplings','Baked Salmon','Lobster Stew'},{325,'Ravager Dog','Buzzard Bites'},{355,'Talbuk Steak','Roasted Clefthoof','Warp Burger'},{375,'Crunchy Serpent',"Mok'Nathal Shortribs"}}

}

function L.Stage(name,rank)for _,s in ipairs(L.stages[name]or{})do if rank<s[1]then return s end end end

function L.Target(level,cap,name)

 local ceiling=level>=50 and 375 or level>=35 and 300 or level>=20 and 225 or level>=10 and 150 or 75

 -- A warning threshold, not a hard stopping cap. Town batches can exceed it.

 return math.min(level*5,cap or 75,ceiling)

end

function L.Trainer(name,pos)

 local best,yards;for _,t in ipairs(H.Locations(name))do if H.Accessible(t)then local d=E.Distance(pos,t);if d and d<=650 and(not yards or d<yards)then best,yards=t,d end end end;return best,yards

end

function L.Context()

 local c=C.Character()or{};local pos=E.CurrentPosition();local sub=call(GetSubZoneText)or''

 local unsafe=call(UnitAffectingCombat,'player')or call(UnitIsDeadOrGhost,'player')or call(UnitOnTaxi,'player')

 local town=call(IsResting)==true

 if L.serviceAt and clock()-L.serviceAt<600 and pos and L.servicePosition then local d=E.Distance(pos,L.servicePosition);if d and d<180 then town=true end end

 local cities={[1453]=true,[1454]=true,[1455]=true,[1456]=true,[1457]=true,[1458]=true,[1947]=true,[1954]=true,[1955]=true}

 if pos and cities[pos.mapID]then town=true end

 local service

 for _,n in ipairs(P.steps or{})do if not n.complete and not n.deferred and(n.kind=='sell'or n.kind=='train')and n.destination then local d=E.Distance(pos,n.destination);if d and d<=180 then town=true;service=n.destination;break end end end

 if call(GetSubZoneText)=='Azure Watch'then town=true end

 return{level=c.level or 1,faction=c.faction,pos=pos,unsafe=unsafe,town=town,service=service,starter=sub=='Ammen Vale'or sub=='Northshire Valley'}

end

function L.Materials(recipe)

 local out,ready={},true

 for _,m in ipairs(recipe.mats or{})do local have=count(m.id);local need=tonumber(m.need);if not need or not have then ready=false end

  local missing=need and have and math.max(0,need-have)or nil

  if not missing or missing>0 then ready=false end

  out[#out+1]={id=m.id,name=m.name or('Item '..tostring(m.id)),need=need,have=have,missing=missing}

 end

 return out,ready and #out>0

end

local colorRank={optimal=3,medium=2,easy=1}

function L.Choose(name,skill)

 local book=P.book[name];if not book or book.rank~=skill.rank then return end

 local stage=L.Stage(name,skill.rank);local recommended={};for i=2,#(stage or{})do recommended[stage[i]]=true end

 local best

 for _,r in ipairs(book.values or{})do if colorRank[r.kind]then

  local mats,ready=L.Materials(r);if #mats>0 then

   local missing=0;for _,m in ipairs(mats)do missing=missing+(m.missing or 100000)end

   local candidate={recipe=r,mats=mats,ready=ready,guaranteed=r.kind=='optimal',recommended=recommended[r.name]==true,missing=missing}

   local function better(a,b)

    if not b then return true end

    -- Client-reported orange outranks convenience and bracket suggestions.

    if a.guaranteed~=b.guaranteed then return a.guaranteed end

    if a.ready~=b.ready then return a.ready end

    if a.recommended~=b.recommended then return a.recommended end

    if colorRank[a.recipe.kind]~=colorRank[b.recipe.kind]then return colorRank[a.recipe.kind]>colorRank[b.recipe.kind]end

    if a.missing~=b.missing then return a.missing<b.missing end

    return a.recipe.name<b.recipe.name

   end

   if better(candidate,best)then best=candidate end

  end

 end end

 return best

end

function L.Training(name,skill,ctx)

 local cap=skill.cap;local faction=ctx.faction

 if cap==75 then return'Learn the next rank from a trainer when eligible; check the trainer requirements and fee.'end

 if cap==150 then

  if name=='First Aid'then return'Buy Expert First Aid - Under Wraps and the Heavy Silk/Mageweave manuals from '..(faction=='Horde'and"Balai Lok'Wein in Dustwallow Marsh"or'Deneb Walker in Arathi Highlands')..'. Learn Silk Bandage before leaving the trainer.'end

  if name=='Cooking'then return'Expert Cookbook: '..(faction=='Horde'and'Wulan in Desolace' or'Shandrina in Ashenvale')..'. Check the book requirements before buying.'end

  if name=='Fishing'then return'Expert Fishing - The Bass and You: Old Man Heming in Booty Bay. Check its requirements before buying.'end

 end

 if cap==225 and name=='First Aid'then return'Triage requires level35 and First Aid225. Visit '..(faction=='Horde'and'Doctor Gregory Victor in Hammerfall' or'Doctor Gustaf VanHowzen in Theramore')..'.'end

 if cap==225 and name=='Cooking'then return'Clamlette Surprise requires level35 and Cooking225. Prepare12 Giant Egg,10 Zesty Clam Meat and 20 Alterac Swiss before visiting Dirge Quikcleave in Gadgetzan.'end

 if cap==225 and name=='Fishing'then return'Nat Pagle, Angler Extreme requires level35 and Fishing225; Nat Pagle is in Dustwallow Marsh. The four quest fish must be caught manually.'end

 if cap==300 then

  if name=='Cooking'then return'Master Cookbook: '..(faction=='Horde'and'Baxter at Thrallmar' or'Gaston at Honor Hold')..'.'end

  if name=='First Aid'then return'Master First Aid - Doctor in the House and Netherweave manuals: '..(faction=='Horde'and'Aresella at Falcon Watch' or'Burko at Temple of Telhamat')..'.'end

  if name=='Fishing'then return'Master Fishing - The Art of Angling: Juno Dufrain in Zangarmarsh.'end

  if name=='Leatherworking'then return'Master Leatherworking: '..(faction=='Horde'and'Barim Spilthoof at Thrallmar' or'Brumman at Honor Hold')..'; Darmari in Shattrath is an alternative.'end

  return'Review the Master rank with an appropriate profession trainer; verify the character-level requirement and fee in game.'

 end

 return'Visit an accessible trainer for the next rank and verify its requirements. Unlocking skill300 does not mean level35 supplies are readily available.'

end

function L.LocalFarm(kind,item,ctx)

 if not F or not ctx.pos then return end

 local route=F.Plan(kind,item,6);local out={}

 for _,p in ipairs(route or{})do out[#out+1]=p end

 return out[1],out

end

function L.Make(name,skill,ctx)

 local target=L.Target(ctx.level,skill.cap,name);local behind=skill.rank<target

 local node={id='paced:'..name..':'..ctx.level,kind='profession',profession=name,category=(name=='Fishing'or name=='Skinning')and'Gathering'or'Crafting',level=ctx.level,pacing=true,target=target}

 node.title=name..' - '..skill.rank..'/'..skill.cap

 local lead=name..' skill '..skill.rank..'/'..skill.cap..'. Catch-up reference: '..target..'; this is not a hard cap.\n\n'

 if skill.rank>=skill.cap then

  if skill.cap>=375 then return end

  if not ctx.town then return end

  local minimum=skill.cap==75 and 10 or skill.cap==150 and 20 or skill.cap==225 and 35 or skill.cap==300 and 50 or 1

  if ctx.level<minimum then return end

  node.title='Review '..name..' training';node.trainingRequired=true;node.body=lead..L.Training(name,skill,ctx)

  if name=='Leatherworking'or name=='Skinning'or skill.cap==75 then node.destination=L.Trainer(name,ctx.pos)end

  return node

 end

 if name=='Fishing'then

  if not behind or not P.PlanFishing then return end

  local plan=P.PlanFishing(skill.rank,skill.cap);local s=plan.site

  if not s or not ctx.pos or s.mapID~=ctx.pos.mapID or not plan.distance or plan.distance>650 then return end

  node.title='Fishing: '..skill.rank..'/'..target;node.areaTask=true;node.destination=copy(s);node.destination.areaTask=true

  node.body=ns.FishingInstructions.Body(s.name,target)

  return node

 end

 if name=='Skinning'then

  if not behind then return end

  if not count(7005)or count(7005)<1 then if not ctx.town then return end;node.title='Buy a Skinning Knife';node.body=lead..'Carry a Skinning Knife before skinning. Buy one from a nearby trade/leatherworking supplier; no supplier position is invented.';return node end

  local item=skill.rank<100 and 2318 or skill.rank<150 and 2319 or skill.rank<200 and 4234 or skill.rank<250 and 4304 or skill.rank<300 and 8170 or 21887

  local point,route=L.LocalFarm('Skinning',item,ctx);if not point then return end

  node.title='Skin local beasts - '..skill.rank..' / '..target;node.areaTask=true;node.destination=copy(point);node.destination.areaTask=true;node.mobIDs={point.npcID};node.farmCandidates=route

  node.body=lead..'Kill, loot, then skin eligible beasts near '..point.name..'. This local circuit uses current-zone source positions and your skill/level, not a fixed website loop. Check terrain and enemies.\n\nKeep leather and hides for Leatherworking. A successful skin does not guarantee a skill point. Stop when on pace or resume questing; no harvest is automated.';return node

 end

 local choice=L.Choose(name,skill);local stage=L.Stage(name,skill.rank)

 if not choice then

  if not ctx.town then return end

  node.title='Review '..name..' recipes';node.trainingRequired=true;node.body=lead..'Open your own '..name..' window with recipe filters cleared so GF can read skill-eligible recipes and reagent counts. A source guide is not proof you know a recipe.'

  if stage then local names={};for i=2,#stage do names[#names+1]=stage[i]end;node.body=node.body..'\n\nSuggested bracket candidates: '..table.concat(names,', ')..'. Learn an available recipe manually; source, reputation and specialization requirements still apply.'end

  node.destination=L.Trainer(name,ctx.pos);return node

 end

 if not ctx.town and not behind then return end

 -- Crafting session admission is checked after material preparation below.

 node.recipe=choice.recipe;node.recipeMaterials=choice.mats

 local batch=math.min(5,math.max(1,(stage and stage[1]or target)-skill.rank))

 if choice.ready then

  local max=math.huge;for _,m in ipairs(choice.mats)do max=math.min(max,math.floor(m.have/m.need))end;batch=math.min(batch,max)

  node.craftReady=true;node.title='Craft '..choice.recipe.name..' - up to '..batch

  node.body=lead..'At this service stop, craft up to '..batch..' '..choice.recipe.name..', then reassess your skill and supplies. The goal may exceed the catch-up reference when materials permit.\nSkill-up: '..(choice.guaranteed and 'Orange in your current recipe book; guaranteed while it remains orange. Reassess after each skill gain.'or'No known orange recipe is available. This is a fallback; yellow/green crafts may not award a skill point.')

 else

  if not behind and not ctx.town then return end

  node.title='Prepare '..choice.recipe.name

  node.body=lead..'Materials for one craft (gather short batches, then reassess):'

  for _,m in ipairs(choice.mats)do node.body=node.body..'\n'..m.name..': '..tostring(m.have or'?')..' / '..tostring(m.need or'?')end

  for _,m in ipairs(choice.mats)do if m.missing and m.missing>0 then local item,_,kind=F.Material(m.id);if item then

   local point,route=L.LocalFarm(kind,item,ctx);if point then node.destination=copy(point);node.destination.areaTask=true;node.areaTask=true;node.category='Gathering';node.mobIDs={point.npcID};node.farmCandidates=route;node.material=item;node.materialTarget=m.need;break end

  end end end

  -- A missing location must not erase the required acquisition step.

  node.body=node.body..'\n\n'..(node.destination and'Use nearby eligible sources in this zone. Drops are not guaranteed; follow accessible ground.'or'No verified local farming destination is available. Keep suitable drops while questing or check suppliers/AH manually; no coordinates or prices are invented.')

 end

 if name=='Cooking'then node.body=node.body..'\n\nUse a cooking fire. Prefer useful fish/meat already gathered; check known recipes before spending them.'end

 if name=='Leatherworking'then node.body=node.body..'\n\nKeep useful hides and Fine Leather Belts for later recipes. Skin suitable nearby beasts; do not travel to a higher-level zone merely to reach a numerical target.'end

 node.body=node.body..'\n\nOpen this profession after skill changes to refresh recipe difficulty. Done defers this batch for10 minutes; Skip defers it until the next level. Actual skill is always read from the game.'

 return node

end

function L.Apply()

 if not P.active or E.db.journey=='Completionist'or F and F.route then return P.steps end

 local ctx=L.Context();if ctx.level<5 or ctx.unsafe or ctx.starter then return P.steps end

 local pending={};local settings=prefs();local selected

 for _,name in ipairs(L.names)do

  local skill=P.skills[name];if skill and type(skill.rank)=='number'and type(skill.cap)=='number'then

   local key=name..':'..ctx.level;local untilTime=settings.deferred[key]

   if not untilTime or clock()>=untilTime then local node=L.Make(name,skill,ctx);if node then pending[#pending+1]=node end end

  end

 end

 L.lastPlans=pending

 -- Replace older duplicate milestones for the five supported professions, keeping other professions intact.

 local supported={};for _,name in ipairs(L.names)do supported[name]=P.skills[name]~=nil end

 local kept={};for _,n in ipairs(P.steps)do if not(n.kind=='profession'and supported[n.profession])then kept[#kept+1]=n end end

 local at=1;while kept[at]and(kept[at].complete or kept[at].deferred or kept[at].kind=='turnin'and(C.QuestState(kept[at].quest)or{}).ready or kept[at].professionChoice)do at=at+1 end

