 for _,node in ipairs(pending)do table.insert(kept,at,node);at=math.min(at+4,#kept+1)end

 P.steps=kept;P.firstPending=nil;for _,n in ipairs(kept)do if not n.complete and not n.deferred then P.firstPending=n.id;break end end

 L.lastPlans=pending;return kept

end

