local worker=CreateFrame('Frame');L.worker=worker;local dirty=false;local full=false;local elapsed=0

for _,event in ipairs({'TRADE_SKILL_SHOW','TRADE_SKILL_UPDATE','SKILL_LINES_CHANGED','BAG_UPDATE_DELAYED','PLAYER_LEVEL_UP','MERCHANT_SHOW','MERCHANT_CLOSED','PLAYER_UPDATE_RESTING','ZONE_CHANGED','PLAYER_ENTERING_WORLD','PLAYER_REGEN_ENABLED'})do pcall(worker.RegisterEvent,worker,event)end

-- Fishing gains/catches update the active checkpoint without rebuilding the whole quest route.

function L.RefreshFishing()

 local current=N.model:Current()

 if not current or not current.pacing or current.profession~='Fishing' or E.db.journey=='Completionist' or F and F.route then return false end

 P.ReadSkills();local skill=P.skills.Fishing;if not skill then return false end

 local ctx=L.Context();if ctx.unsafe or ctx.starter then return false end

 local untilTime=prefs().deferred['Fishing:'..ctx.level];if untilTime and clock()<untilTime then return false end

 local node=L.Make('Fishing',skill,ctx);if not node or node.id~=current.id then return false end

 for i,n in ipairs(P.steps)do if n.id==current.id then P.steps[i]=node;N.Refresh(true);return true end end

 return false

end

worker:SetScript('OnEvent',function(_,event)

 if event=='MERCHANT_SHOW'then L.serviceAt=clock();L.servicePosition=E.CurrentPosition()end

 if event~='SKILL_LINES_CHANGED' and event~='BAG_UPDATE_DELAYED' then full=true end

