  if n.quest==9452 and n.kind=='accept'and n.destination then

   local t=copy(n.destination);t.name='Ammen Ford shore';t.npc='Diktynna';t.minimumSkill=1;t.minimumLevel=5;t.faction='Alliance';P.FishingSites[#P.FishingSites+1]=t;break

  end

 end

end



