  local step=visible[start+i-1];row:Hide();row.stepID=nil

  if step and not hidden and y+40<room then

   step=N.WorkflowLive(step);row.label:SetText(step.title or'');row.label:SetWidth(width-20);row.label:SetHeight(0);row.label:SetWordWrap(true);row.label:SetFont('Fonts\\ARIALN.TTF',18,'');row.category:Hide()

