 if vendor then

  node.acquireRequired=true;node.category='Gathering';node.material=nil;node.materialTarget=nil;node.mobIDs=nil;node.farmCandidates=nil;node.areaTask=nil

  node.title='Buy '..m.missing..' '..(m.name or K.vendorMaterials[m.id]or('Item '..m.id))..' for '..node.recipe.name

  node.destination=K.Supplier(m.id,ctx.pos)

