X.rewards=facts
function X.Enabled()
 return E.db and E.db.journey=='Leveling'and E.db.pace=='Grinding'and not(ns.FarmingPlanner and ns.FarmingPlanner.route)
end
-- These are scheduling estimates, not simulated pathfinding, measured completion times or reward guarantees.
function X.Evaluate(n,c,yards,snapshot)
 local f=facts[n.quest];if not f or f.xp<=0 then return end
 local s=snapshot or X.snapshot[n.quest]or{};local level=tonumber(n.level)or(R.rules[n.quest]or{}).lvl or c.level
 if level<1 then level=c.level end
 local gap=level-c.level;local green=K.greenRange or 5
 local risk=gap>=5 and 4 or gap>=3 and 2.2 or gap>=1 and 1.35 or 1
 local value=f.xp
 -- Old source reward values do not establish today's exact grey-quest XP. Discount their scheduling value.
 if gap< -green then value=value*.1 end
 local remaining=s.remaining
 if remaining==nil then remaining=math.max(1,f.units)end
 local work=40+remaining*25*risk+f.slots*15
 if s.ready or n.kind=='turnin'then work=12 end
 local speed=X.speed or 7
 -- A round-trip allowance for unfinished work prevents a far pickup from looking like free XP.
 local travel=math.max(0,tonumber(yards)or 0)/speed*(s.ready and 1 or 1.5)
 if n.kind=='accept'then work=work+20 end
 local seconds=math.max(12,work+travel)
 return{rate=value*60/seconds,xp=f.xp,weightedXP=value,seconds=seconds,risk=risk,known=true}
end
local function capture(id,state)
 if X.snapshot[id]then return X.snapshot[id]end
 local q=state(id)or{};local s={inLog=q.inLog==true or q.inLog==1,ready=q.ready==true or q.ready==1 or q.complete==true or q.complete==1}
 if s.inLog and C_QuestLog and type(C_QuestLog.GetQuestObjectives)=='function'then
  local ok,goals=pcall(C_QuestLog.GetQuestObjectives,id)
  if ok and type(goals)=='table'and #goals>0 then
   local left,seen=0,false
   for _,g in ipairs(goals)do if not g.optional then local have,need=tonumber(g.numFulfilled),tonumber(g.numRequired)
    if have and need then seen=true;left=left+math.max(0,need-have)elseif g.finished==false then left=left+1 end
   end end
   if seen then s.remaining=left;s.ready=left==0 end
  end
 end
 X.snapshot[id]=s;return s
end
local selectCluster=K.SelectCluster
function K.SelectCluster(c,pos,candidates,state,distance,fallback,nearest)
 local map,yards=selectCluster(c,pos,candidates,state,distance,fallback,nearest)
 if not X.Enabled()then return map,yards end
 local groups={};local continent=R.Continent(pos.mapID)
 for _,v in ipairs(candidates)do
  local n=v.entry.action;capture(n.quest,state)
  local d=v.workDestination or n.destination;local travel=distance(d)
  if travel and travel<=(nearest or travel)+3000 and(not continent or R.Continent(d.mapID)==continent)then
   local key=v.adaptiveOrder and v.adaptiveOrder.key or d.mapID..':'..math.floor(d.x/3)..':'..math.floor(d.y/3)
   local g=groups[key];if not g then g={key=key,map=d.mapID,distance=travel,quests={},xp=0,work=0};groups[key]=g end
   g.distance=math.min(g.distance,travel)
   if not g.quests[n.quest]then local score=X.Evaluate(n,c,0);if score then g.quests[n.quest]=true;g.xp=g.xp+score.weightedXP;g.work=g.work+score.seconds end end
  end
 end
 local best
 for _,g in pairs(groups)do if g.xp>0 then
  -- Shared travel is paid once; overlapping work receives a modest25percent allowance.
  g.rate=g.xp*60/math.max(12,g.work*.75+g.distance/7*1.5)
  if not best or g.rate>best.rate or g.rate==best.rate and g.key<best.key then best=g end
 end end
 X.lastCluster=best
 return best and best.map or map,best and best.distance or yards
end
local build=R.Build
function R.Build(...)
 if X.Enabled()then X.snapshot={};X.speed=7;if type(GetUnitSpeed)=='function'then local ok,v=pcall(GetUnitSpeed,'player');if ok and type(v)=='number'and v>0 then X.speed=math.max(2.5,math.min(v,30))end end end
 return build(...)
end
local questLess=K.QuestLess
function K.QuestLess(a,b,c,pos,distance)
 if not X.Enabled()then return questLess(a,b,c,pos,distance)end
 distance=distance or function(d)return E.Distance(pos,d)end
 local function score(n)return X.Evaluate(n,c,distance(n.workDestination or n.destination))end
 local sa,sb=score(a),score(b)
 if sa and sb and math.abs(sa.rate-sb.rate)>.001 then return sa.rate>sb.rate end
 if (sa~=nil)~=(sb~=nil)then return sa~=nil end
 return questLess(a,b,c,pos,distance)
end
local order=T.Order
function T.Order(rows)
 local ordered,first=order(rows)
 if not X.Enabled()then return ordered,first end
 local c=C.Character();local pos=E.CurrentPosition();if not c or not pos then return ordered,first end
 local protected,scored,unknown={},{},{}
 for index,n in ipairs(ordered)do
  local rule=n.quest and R.rules[n.quest]or{}
  local class=n.quest and(n.classQuest or(tonumber(rule.class)or 0)>0)
  local rank=T.HubRank(n,pos)
  -- Preserve service obligations and nearby completed hand-ins. Accepted class chains remain core progression.
  if not n.quest or n.adaptiveVendor or n.classTraining or n.professionChoice or n.trainingRequired or n.professionFocus or rank==1 or class and(C.QuestState(n.quest)or{}).inLog then protected[#protected+1]=n
  else
   local score=X.Evaluate(n,c,E.Distance(pos,n.workDestination or n.destination))
   if score then scored[#scored+1]={node=n,score=score,index=index}else unknown[#unknown+1]=n end
  end
 end
 table.sort(scored,function(a,b)if math.abs(a.score.rate-b.score.rate)>.001 then return a.score.rate>b.score.rate end;return a.index<b.index end)
 local out={};for _,n in ipairs(protected)do out[#out+1]=n end;for _,v in ipairs(scored)do out[#out+1]=v.node end;for _,n in ipairs(unknown)do out[#out+1]=n end
 -- Active objectives retain their existing focus until completed or skipped; no distance-driven oscillation.
 return out,out[1]and out[1].id or first
end
local slash=SlashCmdList.GRINDINGFOREVER
SlashCmdList.GRINDINGFOREVER=function(message)
 if tostring(message):lower():match('^%s*xp%s*$')then
  ns.Print('XP efficiency: '..(X.Enabled()and'active (Leveling + Grinding)'or'inactive')..'; '..X.rewardCount..' sourced quest rewards. Time/difficulty scores are estimates.')
  local n=N.model and N.model:Current();local c=C.Character();local pos=E.CurrentPosition()
  local score=n and c and pos and X.Evaluate(n,c,E.Distance(pos,n.workDestination or n.destination))
