 if not prices[id]then
  local count,oldest,key=0
  for item,row in pairs(prices)do count=count+1;local stamp=math.max(row.vendor and row.vendor.time or 0,row.auction and row.auction.time or 0);if not oldest or stamp<oldest then oldest,key=stamp,item end end
  if count>=C.maximum and key then prices[key]=nil end
  prices[id]={}
 end
 prices[id][source]={unit=unit,time=clock()};return true
end
function C.Price(id)
 local prices=db();local entry=prices and prices[id];if not entry then return end
 local best,source
 for kind,age in pairs({vendor=604800,auction=86400})do local p=entry[kind]
  if type(p)=='table'and type(p.time)=='number'and type(p.unit)=='number'and p.unit>0 and clock()-p.time>=0 and clock()-p.time<=age and(not best or p.unit<best)then best,source=p.unit,kind end
 end
 return best,source
end
function C.CaptureMerchant()
 for i=1,math.min(500,read(GetMerchantNumItems)or 0)do
  local _,_,price,quantity,available,_,extended=read(GetMerchantItemInfo,i)
  local link=read(GetMerchantItemLink,i);local id=type(link)=='string'and tonumber(link:match('item:(%d+)'))
  if id and not extended and type(quantity)=='number'and quantity>0 and type(price)=='number'and price>0 and available~=0 then C.Observe(id,price/quantity,'vendor')end
 end
end
function C.CaptureAuctions()
 local cheapest={}
 for i=1,math.min(200,read(GetNumAuctionItems,'list')or 0)do
  local _,_,quantity,_,_,_,_,_,_,buyout=read(GetAuctionItemInfo,'list',i)
  local link=read(GetAuctionItemLink,'list',i);local id=type(link)=='string'and tonumber(link:match('item:(%d+)'))
  if id and type(quantity)=='number'and quantity>0 and type(buyout)=='number'and buyout>0 then local price=buyout/quantity;if not cheapest[id]or price<cheapest[id]then cheapest[id]=price end end
 end
 for id,price in pairs(cheapest)do C.Observe(id,price,'auction')end
end
local event=CreateFrame('Frame');event:RegisterEvent('MERCHANT_SHOW');event:RegisterEvent('MERCHANT_UPDATE');event:RegisterEvent('AUCTION_ITEM_LIST_UPDATE')
event:SetScript('OnEvent',function(_,name)if name=='AUCTION_ITEM_LIST_UPDATE'then C.CaptureAuctions()else C.CaptureMerchant()end end);C.frame=event
local fact=S.Fact
S.Fact=function(name,recipe)
 if recipe and recipe.spellID then local row=ns.TBCRecipes[recipe.spellID];if row and ns.TBCProfessions[row.professionID]==name then return row end end
 return fact(name,recipe)
end
-- The client's personal book remains the sole evidence that a recipe is known.
local book=P.ReadBook
P.ReadBook=function(...)
 local result=book(...)
 if read(GetTradeSkillIsLinked)==true or read(C_TradeSkillUI and C_TradeSkillUI.IsTradeSkillLinked)==true then return result end
 local function identify(name,total,info,link,craft)
  local cache=name and P.book[name];if not cache then return end
  local indexed={};for _,r in ipairs(cache.values or{})do indexed[r.name]=r end
  for i=1,math.min(1000,total or 0)do
   local title=read(info,i);local r=title and indexed[title]
   if r then local value=read(link,i);local id=type(value)=='string'and tonumber(value:match('enchant:(%d+)')or value:match('spell:(%d+)'));if id then r.spellID=id end end
  end
 end
 identify(read(GetTradeSkillLine),read(GetNumTradeSkills),GetTradeSkillInfo,GetTradeSkillRecipeLink,false)
 identify(read(GetCraftDisplaySkillLine),read(GetNumCrafts),GetCraftInfo,GetCraftItemLink,true)
 return result
end
local previous=L.Choose
function C.Choose(name,skill)
 local known=P.book[name];if not known or known.rank~=skill.rank then return end
 local ref=H.Reference();local goal=ref and ref.craftSession and ref.profession==name and ref.target
 local points=goal and math.max(0,goal-skill.rank)or S.Minimum(name)
 local vendor=S.VendorAccess(L.Context());local best,hasFacts
 for _,recipe in ipairs(known.values or{})do if recipe.kind=='optimal'then
  local f=S.Fact(name,recipe);local cutoff=f and f.difficulty and tonumber(f.difficulty[2]);if cutoff then hasFacts=true end
  if cutoff and cutoff-skill.rank>=points and skill.cap-skill.rank>=points and points>0 then
   local batch={};local ready,feasible,priced=true,true,true;local raw,total,rareMissing,rareTotal,cost=0,0,0,0,0
   for _,m in ipairs(L.Materials(recipe)or{})do
    local need=m.need and m.need*points;local have=m.have
    if type(need)~='number'or type(have)~='number'or need<=0 then feasible=false;ready=false;priced=false else
     local missing=math.max(0,need-have);local supplier=K.vendorMaterials[m.id]~=nil
     if missing>0 then ready=false;if not supplier or not vendor then feasible=false end end
     if ns.MaterialAcquisitionPolicy.ChanceMaterial(m)then rareTotal=rareTotal+need;rareMissing=rareMissing+missing end
     if not supplier then raw=raw+need end;total=total+need
     local price=C.Price(m.id);if price then cost=cost+price*need else priced=false end
     batch[#batch+1]={id=m.id,name=m.name,need=need,perCraftNeed=m.need,have=have,missing=missing}
    end
   end
   if #batch>0 then
    local a={recipe=recipe,mats=batch,ready=ready,guaranteed=true,feasible=feasible,raw=raw,total=total,batchPoints=points,rareMissing=rareMissing,rareTotal=rareTotal,costKnown=priced,batchCost=priced and cost or nil,costPerPoint=priced and cost/points or nil}
    local function better(x,y)
     if not y then return true end
     if(x.rareMissing>0)~=(y.rareMissing>0)then return x.rareMissing==0 end
     if x.feasible~=y.feasible then return x.feasible end
     if x.costKnown~=y.costKnown then return x.costKnown end
     if x.costKnown and x.costPerPoint~=y.costPerPoint then return x.costPerPoint<y.costPerPoint end
     if x.rareTotal~=y.rareTotal then return x.rareTotal<y.rareTotal end
     if x.raw~=y.raw then return x.raw<y.raw end
     if x.total~=y.total then return x.total<y.total end
     if x.ready~=y.ready then return x.ready end
     return x.recipe.name<y.recipe.name
    end
    if better(a,best)then best=a end
   end
  end
 end end
 if best then return best end
 if not hasFacts then return previous(name,skill)end
end
L.Choose=function(name,skill)if C.professions[name]then return C.Choose(name,skill)end;return previous(name,skill)end
end)(...)
